-- 二级标签改为按顺序匹配：同一分类下排在上面的标签优先。具体商户类型（水果、商超、饮品等）排在
-- 外卖之前，外卖平台作为兜底。并按现有账单为各一级分类补充常用二级标签与关键词。
ALTER TABLE tags ADD COLUMN position INTEGER NOT NULL DEFAULT 0;
UPDATE tags SET position=1 WHERE id='food:groupbuy';
UPDATE tags SET position=6 WHERE id='food:takeout';
-- 用户自建的标签排在内置标签之后，保持原有先后。
UPDATE tags SET position=100+rowid WHERE position=0;
